output_text:
[
  {
    "id": "take_entrance_cart",
    "text": "A shopper must take the cart stationed at the entrance cart station before completing the trip.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "with_cart": "hasCart"
      },
      "events": {
        "take_entrance_cart": {
          "pre": {
            "and": [
              "entrance_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "with_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entrance_cart"
    }
  },
  {
    "id": "items_need_cart_and_free_hands",
    "text": "Shelf items may only be picked up when the shopper has a cart and is not already carrying an item by hand.",
    "abstraction": {
      "state_properties": {
        "with_cart": "hasCart",
        "hands_free": {
          "not": "handFull"
        },
        "proper_item_pickup_context": {
          "and": [
            "with_cart",
            "hands_free"
          ]
        }
      },
      "events": {
        "item_pickup": {
          "pre": "PICKUP_ITEM",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "item_pickup",
          {
            "not": "proper_item_pickup_context"
          }
        ]
      }
    }
  },
  {
    "id": "return_cart_to_bay",
    "text": "Before leaving the supermarket, the shopper must park the cart in the return bay at the front-left service area.",
    "abstraction": {
      "state_properties": {
        "return_bay": "at(0,1)",
        "with_cart": "hasCart",
        "cart_parked_at_return_bay": "cartAt(0,1)"
      },
      "events": {
        "park_cart_at_return_bay": {
          "pre": {
            "and": [
              "return_bay",
              "with_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "park_cart_at_return_bay"
    }
  },
  {
    "id": "exit_unencumbered_after_cart_return",
    "text": "The shopper is forbidden to exit unless the cart is parked in the return bay and the shopper is carrying neither a cart nor a hand item.",
    "abstraction": {
      "state_properties": {
        "cart_parked_at_return_bay": "cartAt(0,1)",
        "unencumbered": {
          "and": [
            {
              "not": "hasCart"
            },
            {
              "not": "handFull"
            }
          ]
        },
        "ready_for_exit": {
          "and": [
            "cart_parked_at_return_bay",
            "unencumbered"
          ]
        }
      },
      "events": {
        "exit_attempt": {
          "pre": "EXIT",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "exit_attempt",
          {
            "not": "ready_for_exit"
          }
        ]
      }
    }
  },
  {
    "id": "checkout_zone_cart_free",
    "text": "Carts are not allowed in the checkout and exit corridor, so the shopper must enter that zone without the cart.",
    "abstraction": {
      "state_properties": {
        "with_cart": "hasCart",
        "checkout_exit_zone": {
          "or": [
            "at(7,2)",
            "at(7,3)",
            "at(7,4)",
            "at(7,5)",
            "at(8,2)",
            "at(8,3)",
            "at(8,4)",
            "at(8,5)",
            "at(9,3)",
            "at(9,4)",
            "at(9,5)"
          ]
        },
        "cart_in_checkout_exit_zone": {
          "and": [
            "with_cart",
            "checkout_exit_zone"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_in_checkout_exit_zone"
    }
  },
  {
    "id": "leave_cart_only_at_designated_spots",
    "text": "A shopper may put the cart down only in a designated cart location: the return bay or the temporary milk-shelf pull-off.",
    "abstraction": {
      "state_properties": {
        "with_cart": "hasCart",
        "return_bay": "at(0,1)",
        "milk_shelf_pull_off": "at(5,4)",
        "designated_cart_drop_spot": {
          "or": [
            "return_bay",
            "milk_shelf_pull_off"
          ]
        }
      },
      "events": {
        "cart_drop": {
          "pre": {
            "and": [
              "with_cart",
              "LEAVE_CART"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cart_drop",
          {
            "not": "designated_cart_drop_spot"
          }
        ]
      }
    }
  },
  {
    "id": "reclaim_milk_pull_off_cart",
    "text": "If a cart is temporarily left at the milk-shelf pull-off, the shopper must reclaim that same cart before exiting.",
    "abstraction": {
      "state_properties": {
        "milk_shelf_pull_off": "at(5,4)",
        "with_cart": "hasCart",
        "cart_at_milk_pull_off": "cartAt(5,4)"
      },
      "events": {
        "temporary_cart_drop_at_milk": {
          "pre": {
            "and": [
              "milk_shelf_pull_off",
              "with_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_at_milk_pull_off"
        },
        "reclaim_milk_pull_off_cart": {
          "pre": {
            "and": [
              "milk_shelf_pull_off",
              "cart_at_milk_pull_off",
              "PICKUP_CART"
            ]
          },
          "post": "with_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "temporary_cart_drop_at_milk",
      "discharge": "reclaim_milk_pull_off_cart"
    }
  },
  {
    "id": "egg_nook_no_cart_lingering",
    "text": "The narrow egg-shelf cell may be entered with a cart only for the immediate purpose of picking up an item there, not for passing through or lingering.",
    "abstraction": {
      "state_properties": {
        "egg_nook": "at(6,4)",
        "with_cart": "hasCart",
        "cart_in_egg_nook": {
          "and": [
            "egg_nook",
            "with_cart"
          ]
        }
      },
      "events": {
        "egg_nook_pickup": {
          "pre": {
            "and": [
              "egg_nook",
              "PICKUP_ITEM"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cart_in_egg_nook",
          {
            "not": "egg_nook_pickup"
          }
        ]
      }
    }
  }
]
